// FromJSON parses a JSON string and returns a Theme.
// On parse error, returns the default theme along with the error.
//
// Since: 2.2
func FromJSON(data string) (fyne.Theme, error) {
	return FromJSONReader(strings.NewReader(data))
}

// FromJSONReader parses JSON from an io.Reader and returns a Theme.
// On parse error, returns the default theme along with the error.
//
// Since: 2.2
func FromJSONReader(r io.Reader) (fyne.Theme, error) {
	var spec jsonThemeSpec
	decoder := json.NewDecoder(r)
	if err := decoder.Decode(&spec); err != nil {
		return DefaultTheme(), err
	}

	theme := &jsonTheme{
		colors:      make(map[string]color.Color),
		colorsDark:  make(map[string]color.Color),
		colorsLight: make(map[string]color.Color),
		sizes:       make(map[string]float32),
		fonts:       make(map[string]fyne.Resource),
		icons:       make(map[string]fyne.Resource),
	}

	// Parse generic colors
	for name, hexStr := range spec.Colors {
		col, err := parseHexColor(hexStr)
		if err != nil {
			fyne.LogError(fmt.Sprintf("Invalid color hex for %s: %s", name, hexStr), err)
			continue
		}

package binding

import (
	"fmt"

	"fyne.io/fyne/v2/storage"
)

// NewSprintf creates a formatted string binding that combines multiple data bindings.
// When any source binding changes, the formatted string is automatically updated.
// Set() parses the string back using fmt.Sscanf and updates each source binding.
//
// Since: 2.2
func NewSprintf(format string, bindings ...DataItem) String {
	s := &sprintfBinding{
		format:   format,
		bindings: bindings,
	}

	// Listen to all source bindings
	for _, b := range bindings {
		b.AddListener(s)
	}

	return s
}

// StringToStringWithFormat wraps a String binding with a format string.
// If format is "%s", returns the original binding directly.
//
// Since: 2.2
func StringToStringWithFormat(str String, format string) String {
	if format == "%s" {
		return str
	}
	return NewSprintf(format, str)
}

